def max_expression_value(s):
    def evaluate(left, op, right):
        if op == '+':
            return left + right
        elif op == '*':
            return left * right

    n = len(s)
    dp = [[[0] * 2 for _ in range(n)] for _ in range(n)]
    ops = []

    # Parse the expression into numbers and operators
    num = ''
    for char in s:
        if char.isdigit():
            num += char
        else:
            ops.append(char)
            dp[len(num) - 1][len(num)][0] = int(num)
            dp[len(num) - 1][len(num)][1] = int(num)
            num = ''

    dp[len(num) - 1][len(num)][0] = int(num)
    dp[len(num) - 1][len(num)][1] = int(num)

    # Fill the DP table
    for length in range(2, n + 1, 2):
        for i in range(n - length + 1):
            j = i + length
            mid = (i + j) // 2
            for k in range(i, mid, 2):
                left_max = max(dp[i][k][0], dp[i][k][1])
                right_max = max(dp[k + 2][j][0], dp[k + 2][j][1])
                if ops[mid // 2] == '+':
                    dp[i][j][0] = max(dp[i][j][0], left_max + right_max)
                    dp[i][j][1] = max(dp[i][j][1], left_max + right_max)
                else:
                    dp[i][j][0] = max(dp[i][j][0], left_max * right_max)
                    dp[i][j][1] = max(dp[i][j][1], left_max * right_max)

    return max(dp[0][n][0], dp[0][n][1])

